'use strict';
const express=require('express'),crypto=require('crypto'),fs=require('fs'),path=require('path');const {db}=require('../db'),{DATA_DIR}=require('../paths');const sharp=require('../../../vendor/upscale/node_modules/sharp'),router=express.Router(),busy=new Set();router.use((req,res,next)=>{const origin=req.get('origin');if(!['127.0.0.1','::1','::ffff:127.0.0.1'].includes(req.socket.remoteAddress)||(origin&&!['http://localhost:'+req.socket.localPort,'http://127.0.0.1:'+req.socket.localPort].includes(origin)))return res.status(403).json({error:'Chỉ dùng trong MUSE trên máy này'});next()});db.exec('CREATE TABLE IF NOT EXISTS movie_studio_projects(id TEXT PRIMARY KEY,payload TEXT NOT NULL,updated_at TEXT NOT NULL)');
const save=p=>{p.updatedAt=new Date().toISOString();db.prepare('INSERT OR REPLACE INTO movie_studio_projects VALUES(?,?,?)').run(p.id,JSON.stringify(p),p.updatedAt);return p},read=id=>{const r=db.prepare('SELECT payload FROM movie_studio_projects WHERE id=?').get(id);if(!r)throw Error('Không tìm thấy Studio phim');return JSON.parse(r.payload)};
function validate(body){const groups={};for(const key of ['characters','backgrounds','accessories']){const list=body.groups?.[key]||[];if(!Array.isArray(list)||list.length>5)throw Error('Mỗi nhóm tối đa 5 ảnh');groups[key]=[...new Set(list.map(String))];for(const tag of groups[key]){const r=db.prepare('SELECT filepath,archived_at FROM ref_images WHERE tag=?').get(tag);if(!r||r.archived_at||!fs.existsSync(r.filepath))throw Error('Ảnh tham chiếu không còn: '+tag)}}const brief=String(body.brief||'').trim();if(!brief||brief.length>25000)throw Error('Brief cần 1–25.000 ký tự');const grid=Number(body.grid)||2,episodes=Number(body.episodes)||1;if(![2,3].includes(grid)||!Number.isInteger(episodes)||episodes<1||episodes>5)throw Error('Chọn storyboard 2×2 / 3×3 và 1–5 tập');return {brief,groups,grid,episodes,ratio:['16:9','9:16','1:1'].includes(body.ratio)?body.ratio:'16:9',title:String(body.title||'Phim mới').slice(0,160)}}
function addRef(file,key){const tag='movie_'+crypto.createHash('sha256').update(key).digest('hex').slice(0,24),old=db.prepare('SELECT tag FROM ref_images WHERE tag=?').get(tag);if(!old){db.prepare("INSERT INTO ref_images(id,tag,filename,filepath,size,mime_type,internal_only,created_at) VALUES(?,?,?,?,?,'image/png',1,datetime('now'))").run(crypto.randomUUID(),tag,path.basename(file),file,fs.statSync(file).size)}return tag}
async function pack(p){const refs=[];for(const key of ['characters','backgrounds','accessories']){const tags=p.groups[key];if(!tags.length)continue;const tile=512,cols=Math.min(3,tags.length),rows=Math.ceil(tags.length/cols),file=path.join(DATA_DIR,'uploads',p.id+'_'+key+'.png'),layers=[];for(let i=0;i<tags.length;i++){const source=db.prepare('SELECT filepath FROM ref_images WHERE tag=?').get(tags[i]);const buffer=await sharp(source.filepath).rotate().resize(tile,tile-40,{fit:'contain',background:'#808080'}).png().toBuffer();layers.push({input:buffer,left:i%cols*tile,top:Math.floor(i/cols)*tile+40});const label=Buffer.from(`<svg width="${tile}" height="40"><rect width="100%" height="100%" fill="#333"/><text x="18" y="28" fill="white" font-size="22">${key} ${i+1}</text></svg>`);layers.push({input:label,left:i%cols*tile,top:Math.floor(i/cols)*tile})}await sharp({create:{width:cols*tile,height:rows*tile,channels:3,background:'#808080'}}).composite(layers).png().toFile(file);refs.push({tag:addRef(file,p.id+key),role:key})}return refs}
async function local(port,url,body){const r=await fetch('http://127.0.0.1:'+port+url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),d=await r.json();if(!r.ok)throw Error(d.error||'Không hoàn thành');return d}
router.get('/',(_,res)=>res.json({projects:db.prepare('SELECT payload FROM movie_studio_projects ORDER BY updated_at DESC').all().map(r=>JSON.parse(r.payload))}));
router.post('/',(req,res)=>{try{res.json(save({id:'movie_'+crypto.randomUUID(),...validate(req.body),state:'draft',plan:null,boards:[]}))}catch(e){res.status(400).json({error:e.message})}});
router.get('/:id',(req,res)=>{try{res.json(read(req.params.id))}catch(e){res.status(404).json({error:e.message})}});
router.post('/:id/plan',(req,res)=>{let p;try{p=read(req.params.id);if(busy.has(p.id)||p.boards.length)throw Error('Dự án đang chạy hoặc đã tạo storyboard');p.state='planning';p.error='';save(p);busy.add(p.id);res.status(202).json(p)}catch(e){return res.status(400).json({error:e.message})}(async()=>{try{const refs=await pack(p);p.packed=refs;save(p);const result=await require('../spaceComponents').aiPrompt('movie_plan_'+crypto.randomUUID(),{prompt:{text:p.brief}},{data:{refTags:refs.map(r=>r.tag),text:`Write a coherent serialized film plan based on the brief and attached role sheets: ${refs.map((r,i)=>'image '+(i+1)+' = '+r.role+' contact sheet; numbered cells are distinct identities').join('; ')}. Maintain identical characters, costume, props, geography and style across episodes. Produce exactly ${p.episodes} episodes, each exactly ${p.grid*p.grid} scenes, each duration 10 seconds maximum (5 or 10). Return ONLY valid JSON without markdown: {"bible":"shared character and continuity description","episodes":[{"title":"...","scenes":[{"title":"...","prompt":"self-contained scene action and visual composition","end":"final pose and continuity handoff","duration":10}]}]}. Keep all dialogue, action order and original meaning. No real media generation in this request.`}});let raw=result.text.trim().replace(/^```(?:json)?\s*/i,'').replace(/```\s*$/,'');const plan=JSON.parse(raw);if(typeof plan.bible!=='string'||!Array.isArray(plan.episodes)||plan.episodes.length!==p.episodes||plan.episodes.some(e=>!Array.isArray(e.scenes)||e.scenes.length!==p.grid*p.grid||e.scenes.some(s=>!String(s.prompt||'').trim()||![5,10].includes(Number(s.duration)))))throw Error('MUSE chưa trả đúng cấu trúc kịch bản. Giữ nguyên brief, bấm viết lại.');p.plan=plan;p.state='review';save(p)}catch(e){p.state='attention';p.error=e.message;save(p)}finally{busy.delete(p.id)}})()});
router.put('/:id/plan',(req,res)=>{try{const p=read(req.params.id);if(p.state!=='review')throw Error('Chỉ sửa trước khi tạo storyboard');const plan=req.body.plan;if(!plan?.bible||plan.episodes?.length!==p.episodes||plan.episodes.some(e=>e.scenes?.length!==p.grid*p.grid||e.scenes.some(s=>!String(s.prompt||'').trim()||![5,10].includes(Number(s.duration)))))throw Error('Kịch bản không hợp lệ');p.plan=plan;res.json(save(p))}catch(e){res.status(400).json({error:e.message})}});
router.post('/:id/storyboards',async(req,res)=>{let p;try{p=read(req.params.id);if(busy.has(p.id)||!p.plan)throw Error('Cần kịch bản đã duyệt');busy.add(p.id);for(let i=0;i<p.plan.episodes.length;i++){if(p.boards.some(b=>b.episode===i+1))continue;const ep=p.plan.episodes[i],prompt=[`Create ONE storyboard image: EXACTLY ${p.grid} columns and ${p.grid} rows of equal cells. Entire canvas landscape 16:9. Each cell is a complete cinematic shot in row-major order. Straight equal boundaries, no gutters, captions, typography or labels. Do not merge panels.`,p.packed.map((r,i)=>'Attached image '+(i+1)+' = '+r.role+' sheet. Use numbered cells only as distinct source identities.').join('\n'),'SHARED CONTINUITY: '+p.plan.bible,'EPISODE: '+ep.title,...ep.scenes.map((s,n)=>'CELL '+(n+1)+': '+s.prompt),'Preserve exact reference face, clothing, props and source artistic style.'].join('\n');const d=await local(req.socket.localPort,'/api/queue/enqueue',{mediaType:'image',prompts:[prompt],refTags:p.packed.map(r=>r.tag),ratio:'16:9'});p.boards.push({episode:i+1,jobId:d.jobs[0].id});save(p)}p.state='storyboards';save(p);await local(req.socket.localPort,'/api/queue/process',{});res.json(p)}catch(e){if(p){p.error=e.message;save(p)}res.status(400).json({error:e.message})}finally{if(p)busy.delete(p.id)}});
async function splitReady(p,port){if(p.filmId)return;const all=p.boards.map(b=>({...b,job:db.prepare('SELECT status,video_url FROM jobs WHERE id=?').get(b.jobId)}));if(all.some(b=>b.job?.status!=='completed'))return;const scenes=[];for(const b of all){if(!/^\/videos\/[^/]+\.(png|jpg|jpeg|webp)$/i.test(b.job.video_url))throw Error('Storyboard không phải ảnh hợp lệ');const file=path.join(DATA_DIR,'videos',path.basename(b.job.video_url)),meta=await sharp(file).metadata();for(let n=0;n<p.grid*p.grid;n++){const x=n%p.grid,y=Math.floor(n/p.grid),left=Math.floor(x*meta.width/p.grid),top=Math.floor(y*meta.height/p.grid),right=Math.floor((x+1)*meta.width/p.grid),bottom=Math.floor((y+1)*meta.height/p.grid),out=path.join(DATA_DIR,'uploads',p.id+'_ep'+b.episode+'_scene'+(n+1)+'.png');await sharp(file).extract({left,top,width:right-left,height:bottom-top}).png().toFile(out);const tag=addRef(out,p.id+b.episode+'_'+n),tileJob='tile_'+crypto.createHash('sha256').update(tag).digest('hex').slice(0,20);const tileName='image_'+tileJob+'.png';fs.copyFileSync(out,path.join(DATA_DIR,'videos',tileName));db.prepare("INSERT OR IGNORE INTO jobs(id,prompt,ref_tags,media_type,status,progress,duration,ratio,attempts,max_retries,timeout_minutes,sort_order,created_at,finished_at,video_url,thumbnail_url) VALUES(?,?,?,'image','completed',100,0,?,0,0,3,0,datetime('now'),datetime('now'),?,?)").run(tileJob,'Storyboard '+p.title+' · tập '+b.episode+' · cảnh '+(n+1),JSON.stringify(p.packed.map(r=>r.tag)),'16:9','/videos/'+tileName,'/videos/'+tileName);const s=p.plan.episodes[b.episode-1].scenes[n];scenes.push({id:crypto.randomUUID(),episode:b.episode,title:s.title||'Cảnh '+(n+1),prompt:s.prompt,end:s.end||'',duration:Number(s.duration),refTags:[tag]})}}const film=await local(port,'/api/films',{title:p.title,bible:p.plan.bible,ratio:p.ratio,refTags:p.packed.map(r=>r.tag),episodeRefs:{},transition:'fade',audio:true,scenes});p.filmId=film.id;p.sceneRefs=scenes.map(s=>({tag:s.refTags[0],episode:s.episode,title:s.title}));p.state='ready';save(p)}
let polling=false;setInterval(async()=>{if(polling)return;polling=true;try{for(const row of db.prepare('SELECT payload FROM movie_studio_projects').all()){const p=JSON.parse(row.payload);if(p.state!=='storyboards')continue;try{const bad=p.boards.map(b=>db.prepare('SELECT status,error FROM jobs WHERE id=?').get(b.jobId)).find(j=>j&&['failed','stopped'].includes(j.status));if(bad){p.state='attention';p.error='Storyboard chưa hoàn thành. Kiểm tra và thử lại tác vụ ảnh trong hàng đợi.';save(p);continue}await splitReady(p,Number(process.env.PORT)||3001)}catch(e){p.state='attention';p.error=e.message;save(p)}}}finally{polling=false}},6000).unref();
router.post('/:id/check',async(req,res)=>{try{const p=read(req.params.id);await splitReady(p,req.socket.localPort);res.json(read(p.id))}catch(e){res.status(400).json({error:e.message})}});
for(const row of db.prepare('SELECT payload FROM movie_studio_projects').all()){const p=JSON.parse(row.payload);if(p.state==='planning'){p.state='attention';p.error='App đã đóng khi viết kịch bản. Kiểm tra tác vụ trợ lý trước khi viết lại.';save(p)}}router.packReferences=pack;module.exports=router;
